const fs = require('fs');
const path = require('path');

const TYPESENSE_API_KEY = fs.readFileSync('/etc/typesense-api-key', 'utf8').trim();
const headers = {
  'X-TYPESENSE-API-KEY': TYPESENSE_API_KEY,
  'Content-Type': 'application/json'
};

async function run() {
  // Check if collection exists
  const checkRes = await fetch('http://127.0.0.1:8108/collections/leaderboard', { headers });
  console.log('Check status:', checkRes.status);
  if (checkRes.status === 200) {
    // Delete it first so we start clean
    console.log('Deleting existing collection...');
    await fetch('http://127.0.0.1:8108/collections/leaderboard', {
      method: 'DELETE',
      headers
    });
  }

  // Create collection
  const schema = {
    name: 'leaderboard',
    fields: [
      { name: 'name', type: 'string', sort: true },
      { name: 'score', type: 'int32' }
    ]
  };
  const createRes = await fetch('http://127.0.0.1:8108/collections', {
    method: 'POST',
    headers,
    body: JSON.stringify(schema)
  });
  console.log('Create status:', createRes.status, await createRes.text());

  // Seed players
  const players = [
    { player_id: 'p1', name: 'Alice', score: 100 },
    { player_id: 'p2', name: 'Bob', score: 100 },
    { player_id: 'p3', name: 'Carol', score: 90 },
    { player_id: 'p4', name: 'Dave', score: 80 },
    { player_id: 'p5', name: 'Eve', score: 70 }
  ];

  for (const player of players) {
    const doc = {
      id: player.player_id,
      name: player.name,
      score: player.score
    };
    const res = await fetch('http://127.0.0.1:8108/collections/leaderboard/documents', {
      method: 'POST',
      headers,
      body: JSON.stringify(doc)
    });
    console.log(`Seeded ${player.player_id}:`, res.status, await res.text());
  }

  // Search/retrieve
  const searchRes = await fetch('http://127.0.0.1:8108/collections/leaderboard/documents/search?q=*&query_by=name&sort_by=score:desc,name:asc', { headers });
  console.log('Search status:', searchRes.status);
  const searchJson = await searchRes.json();
  console.log('Search results:', JSON.stringify(searchJson, null, 2));
}

run().catch(console.error);

