const assert = require('assert');

async function test() {
  console.log('Fetching initial leaderboard...');
  const res1 = await fetch('http://127.0.0.1:8080/api/leaderboard');
  const players1 = await res1.json();
  const bob1 = players1.find(p => p.player_id === 'p2');
  const initialScore = bob1.score;
  console.log(`Bob's initial score: ${initialScore}`);

  console.log('Sending 100 concurrent score updates of +1 each...');
  const promises = [];
  for (let i = 0; i < 100; i++) {
    promises.push(
      fetch('http://127.0.0.1:8080/api/score', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ player_id: 'p2', delta: 1 })
      }).then(r => r.json())
    );
  }

  const results = await Promise.all(promises);
  console.log(`Received ${results.length} responses.`);

  const res2 = await fetch('http://127.0.0.1:8080/api/leaderboard');
  const players2 = await res2.json();
  const bob2 = players2.find(p => p.player_id === 'p2');
  const finalScore = bob2.score;
  console.log(`Bob's final score: ${finalScore}`);

  assert.strictEqual(finalScore, initialScore + 100, `Expected score to be ${initialScore + 100}, but got ${finalScore}`);
  console.log('CONCURRENCY TEST PASSED SUCCESSFULLY!');

  // Clean up: set Bob's score back
  console.log('Cleaning up: restoring Bob\'s score to original...');
  await fetch('http://127.0.0.1:8080/api/score', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ player_id: 'p2', delta: -100 })
  });
}

test().catch(err => {
  console.error('CONCURRENCY TEST FAILED:', err);
  process.exit(1);
});
